#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.

# Run from the laptop: the browser opens here and gh is logged in here. The box's
# values collect in .env.box (git-ignored), which stage 12 copies to the box.
# Box-side steps run over ssh; every one is safe to repeat on a re-run.

REPO=gantover/iceskatesong.com
BOX=${BOX:-rock5itx}
BOX_DIR=${BOX_DIR:-iceskatesong.com}   # relative to the box user's home
DEPLOY_KEY=.ssh/iceskatesong_deploy
DRILL=iceskatesong-drill

# box ARGS... <<'EOF': run a bash script on the box (its login shell may not be bash).
box() { ssh "$BOX" bash -s -- "$@"; }

# reuse_laptop KEY: when .env.box has no KEY yet, offer the laptop .env's value.
reuse_laptop() {
  local v
  [[ -z "$(_existing "$1" || true)" ]] || return 1
  v=$(ENV_FILE=.env _existing "$1" || true)
  [[ -n "$v" ]] && confirm "Reuse $1 from this laptop's .env?" && write_env "$1" "$v"
}

# ask_until KEY "Prompt" REGEX "hint": ask (visible) until the value matches.
ask_until() {
  while :; do
    ask "$1" "$2"
    [[ "${!1}" =~ $3 ]] && return
    warn "$4"
  done
}

ask_secret_until() {
  while :; do
    ask_secret "$1" "$2"
    [[ "${!1}" =~ $3 ]] && return
    warn "$4"
  done
}

ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

run_wizard() {

TOTAL_STAGES=22
cd "$(dirname "$0")/.."
ENV_FILE=.env.box

banner "iceskatesong.com: box setup and R1 launch (#41)"

stage "Reach the box over Tailscale; Docker data on NVMe/SATA"
say "Your ~/.ssh/config points $BOX at rock5itx.local (LAN only). Away from home, ssh needs Tailscale."
if tailscale status 2>/dev/null | grep -qi rock5; then ok "Tailscale is up and lists the box"
else warn "tailscale status doesn't list the box: run 'tailscale up' here and on the box, then re-run."; fi
until ssh -n -o ConnectTimeout=10 "$BOX" true; do
  warn "ssh $BOX failed."
  pause "Fix it (Tailscale login, ssh config), then press Enter to retry."
done
ok "ssh $BOX works"
say "Docker's data directory on the box, and the disk it sits on:"
disk=$(box <<'EOF'
root=$(docker info -f '{{.DockerRootDir}}') && echo "$root" && df -h "$root" | tail -n 1
EOF
) || disk=""
note "${disk:-docker info failed: is your box user in the docker group?}"
[[ "$disk" == *mmcblk* ]] && warn "mmcblk is SD/eMMC: move Docker's data-root to the NVMe/SATA disk before deploying."
pause "The device should be nvme… or sd… (SATA). Press Enter when it is."

stage "Read-only deploy key and clone on the box"
say "A key only the box holds, allowed to read $REPO and nothing else."
pub=$(box "$DEPLOY_KEY" <<'EOF'
[ -f "$1" ] || ssh-keygen -q -t ed25519 -N '' -C "iceskatesong-deploy@$(hostname)" -f "$1"
cat "$1.pub"
EOF
)
if gh repo deploy-key list -R "$REPO" 2>/dev/null | grep -qF "$(cut -d' ' -f2 <<<"$pub")"; then
  ok "deploy key already on GitHub"
else
  keyfile=$(mktemp); printf '%s\n' "$pub" > "$keyfile"
  if gh repo deploy-key add "$keyfile" -R "$REPO" -t "$BOX"; then ok "added a read-only deploy key on GitHub"
  else warn "gh couldn't add the key: add it by hand under the repo's Settings → Deploy keys (write access off)."; fi
  rm -f "$keyfile"
  note "gh-added deploy keys vanish if you revoke gh's token; re-run this stage after a gh logout."
fi
box "$BOX_DIR" "$DEPLOY_KEY" "$REPO" <<'EOF'
if [ -d "$1/.git" ]; then echo "  already cloned in ~/$1"; exit; fi
git clone -c core.sshCommand="ssh -i ~/$2 -o IdentitiesOnly=yes -o StrictHostKeyChecking=accept-new" \
  "git@github.com:$3.git" "$1"
EOF
ok "repo on the box at ~/$BOX_DIR"
if [[ ! -f "$ENV_FILE" ]] && ssh -n "$BOX" test -f "$BOX_DIR/.env" \
   && confirm "The box already has a .env and this laptop has no $ENV_FILE. Copy it here as the starting point?"; then
  (umask 077 && ssh -n "$BOX" cat "$BOX_DIR/.env" > "$ENV_FILE")
  ok "copied the box's .env to $ENV_FILE"
fi
pause

stage "Cloudflare: two-factor authentication"
open_url "https://dash.cloudflare.com/profile/authentication"
step "Under Two-Factor Authentication, turn it on (an authenticator app or a security key)."
step "Store the backup codes in your password manager."
pause "Press Enter once 2FA is on."

stage "Cloudflare Tunnel: a new tunnel routed to web:3000"
ask_until ORIGIN "Public site URL (e.g. https://iceskatesong.com):" '^https://[a-z0-9.-]+$' \
  "Needs the exact https:// URL, no path or trailing slash: SvelteKit rejects the Admin's form posts otherwise."
write_env ORIGIN "$ORIGIN"
host=${ORIGIN#https://}
open_url "https://dash.cloudflare.com/"
step "Networking → Tunnels → Create a tunnel. Name it iceskatesong → Create Tunnel."
step "Pick Docker. Copy only the long token after --token in the command (it starts eyJ). Don't run the command: Compose runs cloudflared."
note "It won't show as connected until the deploy (stage 13). Leave the install screen once you have the token."
ask_secret_until CLOUDFLARE_TUNNEL_TOKEN "Paste the tunnel token:" '^eyJ[A-Za-z0-9_=+/-]+$' \
  "That isn't a bare token: paste just the eyJ… part, without 'docker run' or '--token'."
write_env CLOUDFLARE_TUNNEL_TOKEN "$CLOUDFLARE_TUNNEL_TOKEN"
step "Networking → Tunnels → iceskatesong → Routes → Add route → Published application."
step "Subdomain: empty for $host (or its subdomain). Domain: pick it. Path: empty. Service URL: http://web:3000 → Add route."
warn "If your existing tunnel or a DNS record already uses $host, remove that first, or the route clashes."
pause "Press Enter once the route is added."

stage "Cloudflare Access on /admin and /admin/*"
open_url "https://one.dash.cloudflare.com/"
step "Access controls → Applications → Create new application → Self-hosted and private. Name: iceskatesong admin."
step "Add public hostname: Domain $host, Path admin."
step "Add public hostname again: Domain $host, Path admin/*."
step "Access policies → create a policy: Action Allow, Include, Selector Emails, Value: your email. Select it."
step "Keep the One-time PIN login → Create."
ask_until CF_ACCESS_TEAM_DOMAIN "Team domain (Settings; https://<team>.cloudflareaccess.com):" \
  '^https://[a-z0-9-]+\.cloudflareaccess\.com$' "Use exactly https://<team>.cloudflareaccess.com, no trailing slash: it must equal the JWT issuer."
if curl -fsS -m 10 -o /dev/null "$CF_ACCESS_TEAM_DOMAIN/cdn-cgi/access/certs"; then ok "team domain answers"
else warn "$CF_ACCESS_TEAM_DOMAIN/cdn-cgi/access/certs didn't answer: check the team name."; fi
write_env CF_ACCESS_TEAM_DOMAIN "$CF_ACCESS_TEAM_DOMAIN"
step "Open the application → Configure → Additional settings (or its Overview) → copy the Application Audience (AUD) Tag."
ask_until CF_ACCESS_AUD "Paste the AUD tag:" '^[0-9a-f]{64}$' "An AUD tag is 64 hex characters."
write_env CF_ACCESS_AUD "$CF_ACCESS_AUD"

stage "Cloudflare: Bot Fight Mode off"
say "Bot Fight Mode sets the __cf_bm cookie on every public page, which breaks the Privacy page's no-cookies promise."
open_url "https://dash.cloudflare.com/"
step "Pick $host → Security → Settings → filter 'Bot traffic' → Bot Fight Mode: note whether it was on, then turn it off."
step "While there, leave challenges (Under Attack mode, managed challenges) off for public pages: they set cf_clearance."
pause "Press Enter once Bot Fight Mode is off."

stage "Cloudflare R2: backup bucket and token"
open_url "https://dash.cloudflare.com/"
step "R2 object storage → Create bucket. Name: iceskatesong-backup, location Automatic → Create bucket."
ask_until R2_BUCKET "Bucket name:" '^[a-z0-9][a-z0-9-]{1,62}$' "R2 bucket names are lowercase letters, digits and dashes."
write_env R2_BUCKET "$R2_BUCKET"
step "R2 object storage → Overview → Account Details → API Tokens: Manage → Create Account API token."
step "Permissions: Object Read & Write, scoped to $R2_BUCKET only → Create."
step "The result page shows the S3 endpoint (https://<account id>.r2.cloudflarestorage.com) and both keys. The secret is shown once."
ask_until R2_ENDPOINT "S3 endpoint:" '^https://[0-9a-f]{32}(\.[a-z]+)?\.r2\.cloudflarestorage\.com$' \
  "Expected https://<32-hex account id>[.eu].r2.cloudflarestorage.com, no bucket or slash."
write_env R2_ENDPOINT "$R2_ENDPOINT"
ask R2_ACCESS_KEY_ID "Access Key ID:"
write_env R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
ask_secret R2_SECRET_ACCESS_KEY "Secret Access Key:"
write_env R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"

stage "Healthchecks.io: a ping per nightly backup"
open_url "https://healthchecks.io/"
step "Sign in → Add Check. Name: iceskatesong backup."
step "Schedule: Period 1 day, Grace 2 hours (the backup runs at 03:00 UTC) → Save."
step "Integrations: check Email is on for this check (it is for the account's own address by default)."
step "Copy the check's ping URL (https://hc-ping.com/…)."
ask_secret_until HEALTHCHECKS_URL "Paste the ping URL:" '^https://hc-ping\.com/' "Ping URLs start https://hc-ping.com/."
write_env HEALTHCHECKS_URL "$HEALTHCHECKS_URL"

stage "YouTube Data API key"
reuse_laptop YOUTUBE_API_KEY || {
  open_url "https://console.cloud.google.com/apis/library/youtube.googleapis.com"
  step "Pick (or create) a project → Enable YouTube Data API v3."
  open_url "https://console.cloud.google.com/apis/credentials"
  step "Create credentials → API key. Edit it: API restrictions → Restrict key → YouTube Data API v3 → Save. Copy the key."
  ask_secret YOUTUBE_API_KEY "Paste the API key:"
  write_env YOUTUBE_API_KEY "$YOUTUBE_API_KEY"
}

stage "Anthropic API key and the music spend cap"
reuse_laptop ANTHROPIC_API_KEY || {
  open_url "https://console.anthropic.com/settings/keys"
  step "Create Key, named iceskatesong-box. Copy it (shown once)."
  ask_secret_until ANTHROPIC_API_KEY "Paste the key:" '^sk-ant-' "Anthropic keys start sk-ant-."
  write_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
}
say "Hard per-Import budget for the music LLM; the first full corpus is projected at about \$7."
ask MUSIC_SPEND_CAP_USD "Spend cap in USD [10]:"
write_env MUSIC_SPEND_CAP_USD "${MUSIC_SPEND_CAP_USD:-10}"

stage "Site values and the database password"
say "Shown in every footer and on the legal pages."
ask SITE_OPERATOR_NAME "Operator name [Damian Hubert]:"
write_env SITE_OPERATOR_NAME "${SITE_OPERATOR_NAME:-Damian Hubert}"
ask_until SITE_CONTACT_EMAIL "Public contact email:" '^[^@ ]+@[^@ ]+\.[^@ ]+$' "That isn't an email address."
write_env SITE_CONTACT_EMAIL "$SITE_CONTACT_EMAIL"
say "Named in the crawler's User-Agent so the ISU can reach you; an Import fails without it."
ask_until IMPORT_CONTACT_EMAIL "Import contact email:" '^[^@ ]+@[^@ ]+\.[^@ ]+$' "That isn't an email address."
write_env IMPORT_CONTACT_EMAIL "$IMPORT_CONTACT_EMAIL"
if [[ -n "$(_existing POSTGRES_PASSWORD || true)" ]]; then
  ok "keeping the POSTGRES_PASSWORD already in $ENV_FILE (it only applies when pgdata is first created)"
else
  write_env POSTGRES_PASSWORD "$(openssl rand -hex 24)"   # hex: URL-safe, as compose.yml needs
fi
write_env COMPOSE_PROFILES prod   # adds the backup and cloudflared services

stage "Copy .env to the box"
# Our postgres running means the stack is up and the ports are ours; before that, another service may hold them.
deployed=$(ssh -n "$BOX" "cd $BOX_DIR && docker compose ps -q postgres" 2>/dev/null || true)
if [[ -z "$deployed" ]]; then
  for kp in POSTGRES_PORT:5432 WEB_PORT:8080; do
    k=${kp%%:*}; port=$(_existing "$k" || echo "${kp#*:}")
    if [[ -n "$(ssh -n "$BOX" "ss -ltnH 'sport = :$port'" || true)" ]]; then
      warn "Port $port is taken on the box, so $k needs another (bound to 127.0.0.1 only)."
      ask_until "$k" "Free port for $k:" '^[0-9]+$' "A port number."
      write_env "$k" "${!k}"
    fi
  done
fi
copy=1
if ssh -n "$BOX" test -f "$BOX_DIR/.env"; then
  warn "The box already has ~/$BOX_DIR/.env. It is kept as .env.bak before the copy."
  confirm "Overwrite it with $ENV_FILE?" || copy=0
fi
if (( copy )); then
  scp -q "$ENV_FILE" "$BOX:$BOX_DIR/.env.new"
  box "$BOX_DIR" <<'EOF'
cd "$1" && chmod 600 .env.new && { [ ! -f .env ] || cp -p .env .env.bak; } && mv .env.new .env
EOF
  ok "copied $ENV_FILE to ~/$BOX_DIR/.env"
else
  SKIPPED+=("copy $ENV_FILE to the box")
fi
note "$(ssh -n "$BOX" "ls -l $BOX_DIR/.env" 2>&1)"
pause

stage "Deploy"
if [[ -n "$(ssh -n "$BOX" "cd $BOX_DIR && docker compose ps -q postgres" 2>/dev/null || true)" ]]; then
  ok "already deployed: POSTGRES_* are fixed now. Never remove the pgdata volume: it holds the site's data."
else
  say "No database running yet, so POSTGRES_* take effect on this deploy. Existing pgdata volumes on the box:"
  vols=$(ssh -n "$BOX" "docker volume ls -q | grep pgdata" || true)
  note "${vols:-none}"
  [[ -z "$vols" ]] || warn "A pgdata volume from an earlier try keeps its old password: if it holds nothing you need, remove it (docker volume rm …) first."
fi
if confirm "Run scripts/deploy.sh on the box now? (the first ARM64 build takes a while)"; then
  box "$BOX_DIR" <<'EOF' || warn "the deploy failed: read the output above, fix, and re-run this stage."
cd "$1" && scripts/deploy.sh && docker compose ps
EOF
fi
if box "$BOX_DIR" <<'EOF'
cd "$1" && git merge-base --is-ancestor 8e43634 HEAD && git log -1 --oneline
EOF
then ok "the box runs a revision with the #34/#38 legal pages"
else warn "the box's checkout lacks 8e43634 (#34/#38): push main and deploy again."; fi
for _ in 1 2 3 4 5 6; do
  code=$(curl -sS -m 10 -o /dev/null -w '%{http_code}' "$ORIGIN/" 2>/dev/null || true)
  [[ "$code" == 200 ]] && break
  sleep 10
done
[[ "$code" == 200 ]] && ok "$ORIGIN/ answers 200 through the Tunnel" \
  || warn "$ORIGIN/ answered '$code': check 'docker compose logs cloudflared web' on the box."
pause

stage "Check Access and public cookies from outside"
for p in /admin /admin/anything; do
  r=$(curl -sS -m 10 -o /dev/null -w '%{http_code} %{redirect_url}' "$ORIGIN$p" || true)
  if [[ "$r" == 30[23]\ *cloudflareaccess.com* || "$r" == 30[23]\ */cdn-cgi/access/* ]]; then ok "$p → Access login"
  else warn "$p answered '$r', not an Access redirect: check the application's two paths."; fi
done
for p in / /privacy /terms /sources "/search?q=love" "/api/search?q=love"; do
  c=$(curl -sS -m 10 -D - -o /dev/null "$ORIGIN$p" | grep -i '^set-cookie:' || true)
  if [[ -z "$c" ]]; then ok "$p sets no cookie"
  else warn "$p sets: ${c//$'\r'/}"; fi
done
pause "Fix any ⚠ in Cloudflare, then press Enter."

stage "Review the legal pages"
open_url "$ORIGIN/privacy"; open_url "$ORIGIN/terms"; open_url "$ORIGIN/sources"
step "Read Privacy, Terms and Sources. Check the operator name and contact email in each footer."
note "Wording changes go through the repo and a redeploy; the name and email are SITE_* in $ENV_FILE."
pause "Press Enter once you're happy with the wording."

stage "UptimeRobot: an external uptime check"
open_url "https://dashboard.uptimerobot.com/"
step "New monitor → HTTP(s). URL: $ORIGIN/, interval 5 minutes."
step "Alert contacts: your email → Create monitor. It should turn Up within a few minutes."
pause "Press Enter once it shows Up."

stage "First production Import"
open_url "$ORIGIN/admin"
step "Log in with the one-time PIN Cloudflare emails you."
step "Press Import now. The ISU crawl takes about 1h40m; this page shows its status."
note "Leave this waiting: the pause has no timeout. A re-run replays every stage from the start."
step "When it has finished: read the problems list and note the run time for #41."
pause "Press Enter once the Import has finished."

stage "Search timing on the box (#37's full-data check)"
say "Timed on the box against localhost, so it measures the server, not your network. Bar: well under 100 ms."
box "$(_existing WEB_PORT || echo 8080)" <<'EOF'
for q in pirate love; do
  printf '  %-7s' "$q"
  for i in 1 2 3; do
    curl -s -o /dev/null -w '%{time_total}\n' "http://127.0.0.1:$1/api/search?q=$q" | awk '{printf " %4.0f ms", $1 * 1000}'
  done
  echo
done
EOF
note "The first call warms the cache; post the numbers on #41."
pause

stage "Deployed privacy check in a browser"
say "On the live Home, a Skater, a Piece and a Performance with video: no third-party request before the video click, and no cookies."
step "Easiest: ask Claude to repeat docs/legal-acceptance.md's Playwright check against $ORIGIN (read-only)."
step "By hand: DevTools → Network (Disable cache), load each page: every request goes to $host."
step "Then Application → Cookies: empty. Click the video: only then a youtube-nocookie.com request."
open_url "$ORIGIN/"
pause "Press Enter once all four pages pass."

stage "One backup now; Healthchecks turns green"
if confirm "Run one backup on the box now (pg_dump → R2 → ping)?"; then
  box "$BOX_DIR" <<'EOF' || warn "the backup failed: check the R2_* values and HEALTHCHECKS_URL."
cd "$1" && docker compose run --rm backup backup.sh
EOF
fi
open_url "https://healthchecks.io/"
step "The iceskatesong backup check should show Up with a ping just now."
note "Tomorrow after 03:00 UTC, check it got the nightly ping too."
pause

stage "Restore drill on this laptop"
say "Restores the newest R2 dump into a throwaway Compose project ($DRILL, Postgres on 55432, web on 8090)."
say "Your dev database and its port 5432 are untouched; only the R2_* values are passed in, never the prod profile."
if confirm "Run the drill now? (builds the images locally first)"; then
  drill=(env "COMPOSE_PROJECT_NAME=$DRILL" POSTGRES_PORT=55432 WEB_PORT=8090 ORIGIN=http://localhost:8090
    "R2_BUCKET=$R2_BUCKET" "R2_ENDPOINT=$R2_ENDPOINT" "R2_ACCESS_KEY_ID=$R2_ACCESS_KEY_ID" "R2_SECRET_ACCESS_KEY=$R2_SECRET_ACCESS_KEY")
  # Only web (with postgres and migrate): import would start polling for Imports here.
  if "${drill[@]}" scripts/restore.sh && "${drill[@]}" docker compose up -d web; then
    n=$("${drill[@]}" docker compose exec -T postgres sh -c 'psql -U "$POSTGRES_USER" -d "$POSTGRES_DB" -Atc "select count(*) from performances"') || n="?"
    ok "restored: $n performances"
    note "$(curl -sS -m 10 --retry 10 --retry-connrefused --retry-delay 1 'http://localhost:8090/api/search?q=pirate' | head -c 200)"
    open_url "http://localhost:8090/"
    pause "Browse the restored copy, then press Enter."
  else
    warn "the drill failed: read the output above."
    SKIPPED+=("restore drill")
  fi
  if confirm "Delete the drill project and its volumes ($DRILL only)?"; then
    docker compose -p "$DRILL" down -v --rmi local
  fi
fi

stage "Announce the site"
say "Everything's in place: $ORIGIN is live with Access on /admin, nightly backups and an uptime check."
step "Tick the boxes on #41 (gh issue view 41 --web), with the Import run time and search timings."
step "Announce the site."
pause "Press Enter to finish."

finish
note "Next: after 03:00 UTC tomorrow, check Healthchecks.io received the nightly backup ping."
}

run_wizard "$@"; exit
